//! `fj git-credential` speaks git's credential protocol on stdin/stdout.
//!
//! Every case here uses an `Application` login, which carries no `expires_at`
//! and so never triggers the OAuth refresh path: the binary does nothing but
//! read `keys.json` and print, which keeps these tests offline and
//! deterministic.  `XDG_DATA_HOME` is redirected into a per-test sandbox, since
//! that is what `directories::ProjectDirs` resolves `keys.json` through.
//!
//! The invariant these pin down is git's, not ours: a credential helper that
//! exits nonzero aborts the whole git operation instead of falling through to
//! the next helper or a prompt.  So "no credential for this host" must still be
//! a clean exit with empty stdout.

use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Output, Stdio};

const HOST: &str = "forge.test.invalid";
const TOKEN: &str = "test-token-2f8a";

fn sandbox(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!(
        "fj-gitcred-{}-{}-{}",
        std::process::id(),
        name,
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

fn write_keys(data_home: &Path, body: &str) {
    let dir = data_home.join("forgejo-cli");
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join("keys.json"), body).unwrap();
}

fn application_keys() -> String {
    format!(
        r#"{{"hosts":{{"{HOST}":{{"type":"Application","token":"{TOKEN}"}}}},"aliases":{{}},"default_ssh":[]}}"#
    )
}

fn run(data_home: &Path, args: &[&str], stdin: &str) -> Output {
    let mut child = Command::new(env!("CARGO_BIN_EXE_fj"))
        .args(args)
        // Both are redirected: XDG_DATA_HOME is where keys.json lives, and HOME
        // keeps the pre-0.6 fallback lookup inside the sandbox too, so a stray
        // real keys.json can never satisfy a test.
        .env("XDG_DATA_HOME", data_home)
        .env("HOME", data_home)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn fj");
    child
        .stdin
        .as_mut()
        .unwrap()
        .write_all(stdin.as_bytes())
        .unwrap();
    child.wait_with_output().expect("wait for fj")
}

fn stdout_of(out: &Output) -> String {
    String::from_utf8_lossy(&out.stdout).into_owned()
}

#[test]
fn get_emits_username_and_token_for_a_known_host() {
    let home = sandbox("known");
    write_keys(&home, &application_keys());

    let out = run(&home, &["git-credential", "get"], &format!("protocol=https\nhost={HOST}\n\n"));
    let stdout = stdout_of(&out);

    assert!(out.status.success(), "exit: {:?}, stderr: {}", out.status, String::from_utf8_lossy(&out.stderr));
    assert!(
        stdout.lines().any(|l| l == format!("password={TOKEN}")),
        "no password line in stdout: {stdout:?}"
    );
    assert!(
        stdout.lines().any(|l| l.starts_with("username=")),
        "no username line in stdout: {stdout:?}"
    );
}

#[test]
fn get_is_silent_for_an_unknown_host() {
    let home = sandbox("unknown");
    write_keys(&home, &application_keys());

    let out = run(
        &home,
        &["git-credential", "get"],
        "protocol=https\nhost=someone.else.invalid\n\n",
    );
    let stdout = stdout_of(&out);

    assert!(out.status.success(), "exit: {:?}", out.status);
    assert!(
        !stdout.contains("password="),
        "leaked a credential for an unrelated host: {stdout:?}"
    );
}

#[test]
fn get_exits_clean_when_there_is_no_keyfile() {
    let home = sandbox("nokeys");

    let out = run(&home, &["git-credential", "get"], &format!("protocol=https\nhost={HOST}\n\n"));

    assert!(
        out.status.success(),
        "a missing keys.json must not abort git: {:?}",
        out.status
    );
    assert!(!stdout_of(&out).contains("password="));
}

#[test]
fn store_and_erase_are_no_ops_that_leave_the_keyfile_alone() {
    let home = sandbox("storeerase");
    write_keys(&home, &application_keys());
    let before = std::fs::read_to_string(home.join("forgejo-cli/keys.json")).unwrap();

    for op in ["store", "erase"] {
        let out = run(
            &home,
            &["git-credential", op],
            &format!("protocol=https\nhost={HOST}\nusername=oauth2\npassword=REDACTED"),
        );
        assert!(out.status.success(), "{op} exited {:?}", out.status);
    }

    let after = std::fs::read_to_string(home.join("forgejo-cli/keys.json")).unwrap();
    assert_eq!(before, after, "store/erase must not rewrite keys.json");
}
