// invalidates the token that bought it, and a reused refresh_token is treated as
// compromise evidence rather than a retry.  So two processes that each loaded the
// same keys.json -- say a `git push` going through `fj git-credential` while a
// bare `fj whoami` runs in another terminal -- produce exactly one winner, and
// the loser's grant is dead with no way back but an interactive `fj auth login`.
//
// Serialize the whole load-refresh-save cycle through one advisory lock so that
// cannot happen.  `std::fs::File::lock` is a thin wrapper over flock(2) (BSD
// semantics: the lock belongs to the open file description, and the kernel drops
// it when the process exits), so a crash mid-refresh cannot strand the grant.
//
// The path is overridable through FJ_LOCK_FILE so tests can pin it, and
// otherwise lives beside the user's runtime state.
#[cfg(unix)]
struct RefreshLock(std::fs::File);

#[cfg(unix)]
impl RefreshLock {
    fn acquire() -> eyre::Result<Self> {
        use std::os::unix::fs::OpenOptionsExt;
        let path = refresh_lock_path();
        if let Some(parent) = path.parent() {
            // Best-effort: $XDG_RUNTIME_DIR and /tmp already exist in practice,
            // and a real failure surfaces on the open() below with a better
            // message than a mkdir error would carry.
            let _ = std::fs::create_dir_all(parent);
        }
        let file = std::fs::OpenOptions::new()
            .create(true)
            .write(true)
            .mode(0o600)
            .open(&path)
            .map_err(|e| eyre::eyre!("opening refresh lock {}: {e}", path.display()))?;
        file.lock()
            .map_err(|e| eyre::eyre!("acquiring refresh lock {}: {e}", path.display()))?;
        Ok(Self(file))
    }
}

#[cfg(unix)]
impl Drop for RefreshLock {
    fn drop(&mut self) {
        // flock(2) is released on close and on process exit either way; this is
        // just the tidy path.
        let _ = self.0.unlock();
    }
}

#[cfg(unix)]
fn refresh_lock_path() -> PathBuf {
    let from_env = |k: &str| std::env::var_os(k).filter(|v| !v.is_empty()).map(PathBuf::from);
