//! `fj git-credential` -- a git credential helper backed by fj's own logins.
//!
//! Wiring this into git (`credential.<url>.helper = fj git-credential`) means a
//! `git push` to a forge you are logged into with `fj auth login` authenticates
//! with the same grant, refreshed through the same lock as every other fj
//! command.  The alternative people end up writing -- a shell script that pokes
//! `fj whoami` to force a refresh and then greps keys.json -- races fj itself,
//! and with one-shot refresh tokens that race costs you the login.
//!
//! Two rules come from git, not from us:
//!
//! * A helper that exits nonzero aborts the whole git operation rather than
//!   falling through to the next helper or an interactive prompt.  So every
//!   "we have nothing for this host" path here is a *clean* exit with empty
//!   stdout, and a failed refresh degrades to whatever is still on disk.
//! * stdout is the protocol.  Nothing but `key=value` lines may go there, which
//!   is why this path loads keys through [`KeyInfo::load_quiet`].
//!
//! Operations other than `get` are accepted and ignored on purpose: fj owns its
//! key store, so there is nothing for git to `store` or `erase`, and newer git
//! versions probe helpers with operations (`capability`) that did not exist when
//! this was written.  An unknown operation must not be an error.

use clap::Args;
use url::Url;

use crate::KeyInfo;

#[derive(Args, Clone, Debug)]
pub struct GitCredentialCommand {
    /// git's credential operation: `get`, `store`, `erase`, ... Anything other
    /// than `get` is a no-op.
    operation: Option<String>,
}

/// The fields of git's credential request that we actually use.
#[derive(Default, Debug)]
struct Request {
    protocol: Option<String>,
    host: Option<String>,
}

impl GitCredentialCommand {
    pub async fn run(self, keys: &mut KeyInfo) -> eyre::Result<()> {
        // Drain the request even for operations we ignore: git writes the whole
        // block and a helper that exits early can leave it writing into a closed
        // pipe.
        let request = read_request().await?;

        if self.operation.as_deref() != Some("get") {
            return Ok(());
        }

        if let Some((username, token)) = self.resolve(keys, &request).await {
            // Forgejo ignores the basic-auth username when the password is a
            // token, but git insists on having one.
            println!("username={username}");
            println!("password={token}");
        }
        Ok(())
    }

    /// `None` whenever we cannot answer, which git must see as an empty,
    /// successful response.
    async fn resolve(&self, keys: &mut KeyInfo, request: &Request) -> Option<(String, String)> {
        let host = request.host.as_deref()?;
        let protocol = request.protocol.as_deref().unwrap_or("https");
        let url = Url::parse(&format!("{protocol}://{host}")).ok()?;
        let url = keys.deref_alias(url);

        // Check before refreshing: an unknown host must not take the refresh
        // lock, let alone spend a token.
        keys.get_login(&url)?;

        // Refreshes if the grant is expired, under the lock, and saves the
        // rotation. Best-effort by design: on failure we fall through to the
        // token on disk rather than handing git an error, which would abort the
        // operation instead of letting it try and report a real auth failure.
        let _ = keys.get_api(&url).await;

        // Re-resolve: `get_api` re-reads keys.json under the lock, so the login
        // we looked at above may be a different object now.
        let login = keys.get_login(&url)?;
        Some(("oauth2".to_owned(), login.token().to_owned()))
    }
}

/// Read git's `key=value` block from stdin, terminated by a blank line or EOF.
async fn read_request() -> eyre::Result<Request> {
    tokio::task::spawn_blocking(|| {
        use std::io::BufRead;

        let mut request = Request::default();
        let stdin = std::io::stdin();
        let mut line = String::new();
        loop {
            line.clear();
            if stdin.lock().read_line(&mut line)? == 0 {
                break;
            }
            let trimmed = line.trim_end_matches(['\n', '\r']);
            if trimmed.is_empty() {
                break;
            }
            // Unknown keys are ignored rather than rejected: git sends
            // `path`, `username`, `wwwauth[]` and more depending on version
            // and config, and the set grows.
            if let Some((key, value)) = trimmed.split_once('=') {
                match key {
                    "protocol" => request.protocol = Some(value.to_owned()),
                    "host" => request.host = Some(value.to_owned()),
                    _ => {}
                }
            }
        }
        Ok(request)
    })
    .await?
}
