/// The point of the whole change: a refresh cannot start while another process
/// is inside one.
///
/// The test process itself holds the advisory lock (flock(2) is owned by the
/// open file description, so a lock taken here really does exclude the child),
/// then watches `fj git-credential get` fail to make progress until it is
/// released. No network: the login is an `Application` token, so the child
/// blocks on the lock that guards the refresh, not on a refresh.
#[test]
fn get_waits_for_another_process_to_leave_the_refresh_lock() {
    use std::fs::File;
    use std::time::{Duration, Instant};

    let home = sandbox("lockwait");
    write_keys(&home, &application_keys());
    let lock_file = home.join("refresh.lock");

    let held = File::create(&lock_file).unwrap();
    held.lock().expect("test process takes the lock");

    let mut child = Command::new(env!("CARGO_BIN_EXE_fj"))
        .args(["git-credential", "get"])
        .env("XDG_DATA_HOME", &home)
        .env("HOME", &home)
        .env("FJ_LOCK_FILE", &lock_file)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn fj");
    child
        .stdin
        .take()
        .unwrap()
        .write_all(format!("protocol=https\nhost={HOST}\n\n").as_bytes())
        .unwrap();

    // Give it long enough that "still running" means blocked, not merely slow to
    // start: process spawn plus a keys.json read is microseconds of work.
    std::thread::sleep(Duration::from_millis(750));
    assert!(
        child.try_wait().unwrap().is_none(),
        "fj answered while another process held the refresh lock -- refreshes are not serialized"
    );

    let released = Instant::now();
    held.unlock().unwrap();

    let out = child.wait_with_output().unwrap();
    assert!(
        out.status.success(),
        "exit after lock release: {:?}, stderr: {}",
        out.status,
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        String::from_utf8_lossy(&out.stdout)
            .lines()
            .any(|l| l == format!("password={TOKEN}")),
        "no credential after the lock was released: {:?}",
        String::from_utf8_lossy(&out.stdout)
    );
    assert!(
        released.elapsed() < Duration::from_secs(10),
        "took {:?} to proceed after release",
        released.elapsed()
    );
}
