//! `fj git-credential` speaks git's credential protocol on stdin/stdout.
//!
//! Every case here uses an `Application` login, which carries no `expires_at`
//! and so never triggers the OAuth refresh path: the binary does nothing but
//! read `keys.json` and print, which keeps these tests offline and
//! deterministic.  `XDG_DATA_HOME` is redirected into a per-test sandbox, since
//! that is what `directories::ProjectDirs` resolves `keys.json` through.
//!
//! Two invariants here are git's, not ours:
//!
//! * A credential helper that exits nonzero aborts the whole git operation
//!   instead of falling through to the next helper or a prompt.  So "no
//!   credential for this host" must still be a clean exit with empty stdout.
//! * stdout is the protocol, so nothing but `key=value` lines may appear there.

use std::fs::File;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Output, Stdio};
use std::time::{Duration, Instant};

const HOST: &str = "forge.test.invalid";
const TOKEN: &str = "test-token-2f8a";

/// A scratch `XDG_DATA_HOME`, removed on success and kept on failure.
///
/// Kept-on-failure is the point: a panic leaves the keys.json and lock file
/// behind to look at, while a green run leaves nothing in /tmp.
struct Sandbox {
    path: PathBuf,
}

impl Sandbox {
    fn new(name: &str) -> Self {
        let path = std::env::temp_dir().join(format!(
            "fj-gitcred-{}-{}-{}",
            std::process::id(),
            name,
            Instant::now().elapsed().as_nanos() as u64 ^ rand_ish()
        ));
        std::fs::create_dir_all(&path).unwrap();
        Self { path }
    }

    fn path(&self) -> &Path {
        &self.path
    }

    fn keys_json(&self) -> PathBuf {
        self.path.join("forgejo-cli/keys.json")
    }

    fn write_keys(&self, body: &str) {
        let dir = self.path.join("forgejo-cli");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("keys.json"), body).unwrap();
    }
}

impl Drop for Sandbox {
    fn drop(&mut self) {
        if std::thread::panicking() {
            eprintln!("test failed; leaving {} in place", self.path.display());
            return;
        }
        let _ = std::fs::remove_dir_all(&self.path);
    }
}

/// Enough entropy to avoid collisions between same-named tests in one run,
/// without pulling in a dev-dependency for it.
fn rand_ish() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .subsec_nanos() as u64
}

fn application_keys() -> String {
    format!(
        r#"{{"hosts":{{"{HOST}":{{"type":"Application","token":"{TOKEN}"}}}},"aliases":{{}},"default_ssh":[]}}"#
