        // fallback lookup inside the sandbox too, so a real keys.json on the
        // machine can never satisfy a test.
        .env("XDG_DATA_HOME", sandbox.path())
        .env("HOME", sandbox.path())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
