        .unwrap()
        .write_all(get_request().as_bytes())
        .unwrap();

    // Long enough that "still running" means blocked rather than slow to start:
    // spawning and reading keys.json is microseconds of work.
    std::thread::sleep(Duration::from_millis(750));
    assert!(
        child.try_wait().unwrap().is_none(),
        "fj answered while another process held the refresh lock -- refreshes are not serialized"
    );

    let released = Instant::now();
    held.unlock().unwrap();
    let out = child.wait_with_output().unwrap();

    assert!(
        out.status.success(),
        "exit after release: {:?}, stderr: {}",
        out.status,
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(has_credential(&out), "no credential after release");
    assert!(
        released.elapsed() < Duration::from_secs(10),
        "took {:?} to proceed after release",
        released.elapsed()
    );
}

/// ...but the wait is bounded, and giving up still answers git.
///
/// A holder that never makes progress (a suspended laptop, a process killed
/// without releasing) must not wedge git forever. After FJ_LOCK_WAIT_SECS the
/// refresh is abandoned and the token already on disk is served, which is
/// exactly what the shell helper's `flock -w 60 ... || true` did.
#[test]
fn get_gives_up_on_a_wedged_lock_and_serves_the_stored_token() {
    let sb = Sandbox::new("lockbound");
    sb.write_keys(&application_keys());
    let lock_file = sb.path().join("refresh.lock");

    let held = File::create(&lock_file).unwrap();
    held.lock().expect("test process takes the lock");

    let started = Instant::now();
    let mut child = fj(&sb, &["git-credential", "get"])
        .env("FJ_LOCK_FILE", &lock_file)
        .env("FJ_LOCK_WAIT_SECS", "1")
        .spawn()
        .expect("spawn fj");
    child
        .stdin
        .take()
        .unwrap()
        .write_all(get_request().as_bytes())
        .unwrap();

    // Never released: the child must come back on its own.
    let out = child.wait_with_output().unwrap();
    let waited = started.elapsed();

    assert!(
        out.status.success(),
        "a wedged lock must not abort git: {:?}, stderr: {}",
        out.status,
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        has_credential(&out),
        "gave up on the lock but served no credential: {:?}",
        stdout_of(&out)
    );
    assert!(
        waited >= Duration::from_secs(1),
        "returned in {waited:?}, so it never waited for the lock at all"
    );
    assert!(
        waited < Duration::from_secs(20),
        "waited {waited:?} with FJ_LOCK_WAIT_SECS=1 -- the bound is not being honored"
    );

    drop(held);
}
